def main(media):
    for name, path in ICONS.items():
        svg = f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24"><path fill="#000000" d="{path}"/></svg>\n'
        (Path(media) / f"ic_{name}.svg").write_text(svg)


if __name__ == "__main__":
    main(sys.argv[1])
